#!/usr/bin/env Rscript
# ==============================================================================
# Merge 2023-2025 Data into Unified Database
# ==============================================================================
#
# Purpose: Merge app/2023_compliance/ and app/2025-24/ into unified app/2023-24-25/
#
# Input:  app/2023_compliance/*.rds (2023 data in 2025 schema)
#         app/2025-24/*.rds (2024-2025 data)
# Output: app/2023-24-25/*.rds (unified 3-season database)
#
# Author: Generated by Claude Code
# Date: 2026-03-07
# ==============================================================================

library(tidyverse)
library(dm)
library(glue)
library(fs)
