# ==============================================================================
# Configuration
# ==============================================================================

INPUT_2023 <- "app/2023_compliance"
INPUT_2025 <- "app/2025-24"
OUTPUT_DIR <- "app/2023-24-25"

# Create output directory
dir_create(OUTPUT_DIR, recurse = TRUE)

# Initialize validation report
validation_results <- list()
merge_log <- list()

cat("\n")
cat("╔══════════════════════════════════════════════════════════════╗\n")
cat("║  2023-2025 Unified Database Merge                            ║\n")
cat("╚══════════════════════════════════════════════════════════════╝\n")
cat("\n")
cat("Input 2023:  ", INPUT_2023, "\n")
cat("Input 2025:  ", INPUT_2025, "\n")
cat("Output:      ", OUTPUT_DIR, "\n")
cat("\n")

# ==============================================================================
# Helper Functions
# ==============================================================================

# Log merge operation
log_merge <- function(db_name, table_name, rows_2023, rows_2025, rows_merged, notes = "") {
  merge_log[[length(merge_log) + 1]] <<- list(
    database = db_name,
    table = table_name,
    rows_2023 = rows_2023,
    rows_2025 = rows_2025,
    rows_merged = rows_merged,
    notes = notes
  )
}

# Validate row counts
validate_counts <- function(name, expected, actual, allow_dedup = FALSE) {
  if (allow_dedup) {
    if (actual > expected) {
      cat("  ⚠️  ", name, ": ", actual, " rows (expected ≤ ", expected, " with deduplication)\n", sep = "")
      validation_results[[name]] <<- list(status = "WARNING", expected = expected, actual = actual)
      return(FALSE)
    }
  } else {
    if (actual != expected) {
      cat("  ❌ ", name, ": ", actual, " rows (expected ", expected, ")\n", sep = "")
      validation_results[[name]] <<- list(status = "FAIL", expected = expected, actual = actual)
      return(FALSE)
    }
  }
  cat("  ✓ ", name, ": ", actual, " rows\n", sep = "")
  validation_results[[name]] <<- list(status = "PASS", expected = expected, actual = actual)
  return(TRUE)
}

# Validate temporal ordering
validate_temporal <- function(df, name) {
  if ("season" %in% names(df)) {
    seasons <- df %>% distinct(season) %>% pull() %>% sort()
    expected_seasons <- c(2023, 2024, 2025)

    if (!all(seasons %in% expected_seasons)) {
      cat("  ⚠️  ", name, ": Unexpected seasons: ", paste(seasons, collapse = ", "), "\n", sep = "")
      return(FALSE)
    }

    cat("  ✓ ", name, ": Seasons ", paste(seasons, collapse = ", "), "\n", sep = "")
  }
  return(TRUE)
}

# Validate list columns
validate_list_columns <- function(df, name, list_cols) {
  for (col in list_cols) {
    if (col %in% names(df)) {
      if (!is.list(df[[col]])) {
        cat("  ❌ ", name, "$", col, ": Not a list column\n", sep = "")
        return(FALSE)
      }
      if (any(sapply(df[[col]], is.null))) {
        cat("  ⚠️  ", name, "$", col, ": Contains NULL values\n", sep = "")
      }
    }
  }
  return(TRUE)
}

# Merge with preference for non-NA values from 2025
merge_with_priority <- function(df1_2023, df2_2025, key_cols, prefer_2025 = TRUE) {
  if (prefer_2025) {
    # Start with 2025 data (more recent)
    merged <- df2_2025

    # Add 2023 rows not in 2025
    df1_anti <- df1_2023 %>%
      anti_join(df2_2025, by = key_cols)

    merged <- bind_rows(merged, df1_anti)
  } else {
    # Simple union (for temporal data)
    merged <- bind_rows(df1_2023, df2_2025)
  }

  return(merged)
}

# ==============================================================================
# 1. Merge ffa_db.rds
