# ──────────────────────────────────────────────────────────────────

cat("  ⚙️  ffa_player_ids: Merging with priority to 2025\n")

# Load missing IDs supplement
missing_ids <- readRDS(file.path(INPUT_2023, "missing_player_ids.rds"))

# Start with 2025 (most current)
ffa_player_ids_merged <- ffa_db_2025$ffa_player_ids

# Add 2023 players not in 2025
ffa_player_ids_2023_only <- ffa_db_2023$ffa_player_ids %>%
  anti_join(ffa_player_ids_merged, by = "id")

# Add missing IDs not already present
missing_ids_new <- missing_ids %>%
  anti_join(ffa_player_ids_merged, by = "id") %>%
  anti_join(ffa_player_ids_2023_only, by = "id")

# Combine all
ffa_player_ids_merged <- bind_rows(
  ffa_player_ids_merged,
  ffa_player_ids_2023_only,
  missing_ids_new
)

log_merge("ffa_db", "ffa_player_ids",
          nrow(ffa_db_2023$ffa_player_ids),
          nrow(ffa_db_2025$ffa_player_ids),
          nrow(ffa_player_ids_merged),
          glue("Includes {nrow(missing_ids_new)} from missing_player_ids.rds"))

