                nrow(ffa_projtable_merged))
validate_temporal(ffa_projtable_merged, "ffa_projtable")

# ──────────────────────────────────────────────────────────────────
# 1.4 ffa_proj_source_points: Simple union
# ──────────────────────────────────────────────────────────────────

cat("  ⚙️  ffa_proj_source_points: Merging temporal data\n")

ffa_proj_source_points_merged <- bind_rows(
