                nrow(ffa_scrape_merged))

# ──────────────────────────────────────────────────────────────────
# 1.6 Rebuild dm object
# ──────────────────────────────────────────────────────────────────

cat("  ⚙️  Rebuilding dm object with constraints\n")

ffa_db_merged <- dm(
  ffa_player_ids = ffa_player_ids_merged,
  ffa_players = ffa_players_merged,
  ffa_projtable = ffa_projtable_merged,
  ffa_proj_source_points = ffa_proj_source_points_merged,
  ffa_scrape = ffa_scrape_merged
) %>%
  # Add primary keys
  dm_add_pk(ffa_player_ids, id) %>%
  dm_add_pk(ffa_players, c(id, pos)) %>%
  dm_add_pk(ffa_projtable, c(season, week, tag, timestamp, avg_type, id, pos)) %>%
  dm_add_pk(ffa_proj_source_points, c(season, week, tag, timestamp, data_src, id, pos)) %>%
  dm_add_pk(ffa_scrape, c(season, week, tag, timestamp)) %>%
  # Add foreign keys (check = FALSE due to known violations)
  dm_add_fk(ffa_players, id, ffa_player_ids, check = FALSE) %>%
  dm_add_fk(ffa_projtable, c(id, pos), ffa_players, check = FALSE) %>%
  dm_add_fk(ffa_projtable, c(season, week, tag, timestamp), ffa_scrape) %>%
  dm_add_fk(ffa_proj_source_points, c(id, pos), ffa_players, check = FALSE) %>%
  dm_add_fk(ffa_proj_source_points, c(season, week, tag, timestamp), ffa_scrape)

# Check constraints
cat("\n  🔍 Examining constraints:\n")
constraint_results <- dm_examine_constraints(ffa_db_merged)
print(constraint_results)

saveRDS(ffa_db_merged, file.path(OUTPUT_DIR, "ffa_db.rds"))
cat("\n  💾 Saved: ", file.path(OUTPUT_DIR, "ffa_db.rds"), "\n\n", sep = "")

