nfl_round_db_2025 <- readRDS(file.path(INPUT_2025, "nfl_round_db.rds"))

# Get table names from both databases
tables_2023 <- names(nfl_round_db_2023)
tables_2025 <- names(nfl_round_db_2025)
all_tables <- union(tables_2023, tables_2025)

merged_tables <- list()

for (table_name in all_tables) {
  cat("  ⚙️  ", table_name, ": Merging temporal data\n", sep = "")

  df_2023 <- if (table_name %in% tables_2023) nfl_round_db_2023[[table_name]] else tibble()
  df_2025 <- if (table_name %in% tables_2025) nfl_round_db_2025[[table_name]] else tibble()

  merged_tables[[table_name]] <- bind_rows(df_2023, df_2025)

  log_merge("nfl_round_db", table_name,
            nrow(df_2023),
            nrow(df_2025),
            nrow(merged_tables[[table_name]]))

  validate_counts(paste0("nfl_round_db$", table_name),
                  nrow(df_2023) + nrow(df_2025),
                  nrow(merged_tables[[table_name]]))
}

# Rebuild dm object (using schema from 2025 as reference)
cat("\n  ⚙️  Rebuilding dm object\n")

# Check which tables exist and build dm accordingly
nfl_round_db_merged <- dm(!!!merged_tables)

# Add keys based on documented schema
if ("matchups_games" %in% names(nfl_round_db_merged)) {
  nfl_round_db_merged <- nfl_round_db_merged %>%
    dm_add_pk(matchups_games, c(season, week, matchupId))
