# 6. Merge nfl_recap_db.rds
# ==============================================================================

cat("──────────────────────────────────────────────────────────────\n")
cat("📦 Processing nfl_recap_db.rds\n")
cat("──────────────────────────────────────────────────────────────\n")

nfl_recap_db_2023 <- readRDS(file.path(INPUT_2023, "nfl_recap_db.rds"))
nfl_recap_db_2025 <- readRDS(file.path(INPUT_2025, "nfl_recap_db.rds"))

cat("  ⚙️  Merging recap narratives (with list columns)\n")

# Get all tables from both databases
tables_2023 <- names(nfl_recap_db_2023)
tables_2025 <- names(nfl_recap_db_2025)
all_tables <- union(tables_2023, tables_2025)

merged_recap_tables <- list()

for (table_name in all_tables) {
  cat("  ⚙️  ", table_name, "\n", sep = "")

  df_2023 <- if (table_name %in% tables_2023) nfl_recap_db_2023[[table_name]] else tibble()
  df_2025 <- if (table_name %in% tables_2025) nfl_recap_db_2025[[table_name]] else tibble()

  merged_recap_tables[[table_name]] <- bind_rows(df_2023, df_2025)

  log_merge("nfl_recap_db", table_name,
            nrow(df_2023),
            nrow(df_2025),
            nrow(merged_recap_tables[[table_name]]))

  validate_counts(paste0("nfl_recap_db$", table_name),
                  nrow(df_2023) + nrow(df_2025),
                  nrow(merged_recap_tables[[table_name]]))
}

nfl_recap_db_merged <- dm(!!!merged_recap_tables)

saveRDS(nfl_recap_db_merged, file.path(OUTPUT_DIR, "nfl_recap_db.rds"))
cat("\n  💾 Saved: ", file.path(OUTPUT_DIR, "nfl_recap_db.rds"), "\n\n", sep = "")

